"""Reconcile physical NROM logs with source-defined inclusive accounting."""
import argparse,hashlib,json,re
from pathlib import Path
from nes_delta231 import BASE,ROOT,sha
p=argparse.ArgumentParser();p.add_argument('--out',required=True,type=Path);a=p.parse_args()
d=BASE/'probes/nes-nrom469/hardware01';b=(d/'nes-budget-227.txt').read_text();last=dict(x.split('=',1) for x in (d/'nes-game-last-227.txt').read_text().splitlines() if '=' in x)
columns=re.search(r'^columns=(.*)$',b,re.M)[1].split(',');bins=[dict(zip(columns,[int(x,16) for x in m[1].split(',')])) for m in re.finditer(r'^b\d+=(.*)$',b,re.M)];assert len(bins)==12 and all(len(x)==23 for x in bins)
total={k:(max if k=='maxgap' else sum)(v[k] for v in bins) for k in columns};n=total['frames'];assert n==int(last['native_frames'])==899
wirekeys=['ingress','e8','e9','e0','e1','other'];wire=sum(total[k] for k in wirekeys);assert wire==int(last['native_wire_bytes']);assert total['plan']==total['planner_ticks']+total['begin_ticks']+total['finish_ticks']
assert total['callback_ticks']<=total['planner_ticks'];freq=2625000;framebudget=1000/60
wirems=lambda count:count*8/freq*1000/n
phases={k:{'ticks_10ms':total[k],'total_seconds':total[k]/100,'mean_ms_per_completed_frame':total[k]*10/n} for k in ['recv','plan','seal']}
source=BASE/'probes/nes-nrom418/arm01/src';src={name:sha(source/name) for name in ['nes_native_runtime165.c','nes_native165.c','nes_plan_service200.c','nes_sink_window184.c','nes_native_sink165.c','nes_native165_bulk.inc','nes_game149_spi.inc','nes_runtime_board165.inc','nes_budget210.c']}
profile_recv=int(last['profile_receive_ticks']);transactions=int(last['native_transactions']);fixedwait=transactions*8/1000/n
r={'merged_base':'8d472d50df7c396efac8426bb4de62cca8ce0346','firmware418_sha256':sha(source/'obj-nes-100/firmware.stm'),'input_sha256':{name:sha(d/name) for name in ['nes-budget-227.txt','nes-game-last-227.txt','nes-progress-227.txt']},'source_sha256':src,'frames':n,'window_seconds':60.06,'mean_ms_per_display':60060/n,'display_rate':n/60.06,'target_ms':framebudget,'phases':phases,'receive_tick_disagreement':total['recv']-profile_recv,'accounted_ms_per_frame':sum(total[k] for k in ['recv','plan','seal'])*10/n,'unassigned_ms_per_frame':(60060-sum(total[k] for k in ['recv','plan','seal'])*10)/n,'wire':{k:{'bytes':total[k],'bytes_per_frame':total[k]/n,'ideal_ms_per_frame':wirems(total[k])} for k in wirekeys},'total_wire_bytes':wire,'total_wire_ms_per_frame':wirems(wire),'payload_only_ms_per_frame':wirems(total['d1_payload']),'wire_accounting_scope':'native_runtime165 transfer only; direct observer/screen service SPI is outside these byte/transaction counters; physical bus occupancy is at least this value','spi_hz_from_source':freq,'wire_occupancy':wire*8/freq/60.06,'minimum_fixed_wait_ms_per_frame':fixedwait,'wire_plus_explicit_wait_ms_per_frame':wirems(wire)+fixedwait,'target_max_bytes_wire_only':freq/8/60,'minimum_wire_byte_reduction_fraction':1-(freq/8/60)/(wire/n),'target_wire8ms_bytes':freq/8*.008,'wire_reduction_for8ms_fraction':1-(freq/8*.008)/(wire/n),'transactions':transactions,'status_counts_exact':{'E0':total['e0']//20,'E8':total['e8']//20,'D0':total['d0_clock']//8},'counts':total,'warm_bin2':bins[2],'planner_excluding_emit_callback_ms':(total['planner_ticks']-total['callback_ticks'])*10/n,'receive_above_ingress_wire_ms':total['recv']*10/n-wirems(total['ingress']),'scenario_floor_ms':{'remove_receive_phase_only':(60060-total['recv']*10)/n,'remove_plan_phase_only':(60060-total['plan']*10)/n,'remove_seal_phase_only':(60060-total['seal']*10)/n},'SPI5_25MHz_caution':{'half_period_ns':1e9/(2*5250000),'previous_conditional_reply_envelope_ns':164.848,'bound_fits_half_period':False},'diagnostic_observer_period_ms':50,'deadline_receiver_error':{'runtime_result':int(last['native_result']),'receiver_error':int(last['native_receiver_error']),'split_transfer_failure_vs_crc_required':True},'fps60_proven':False,'limits':['10ms aggregate counters, no single-frame WCET','wire ideal lower bound, not observed occupancy intervals','phase timers include transfer/service/wait; wire times must not be added again','callbacks are inside planner; BEGIN/FINISH are inside plan','SEAL includes validation, queue drain, DMA, VBlank, ACK polling; not pure DMA','capture scheduling and ownership overlap unmeasured','static NROM workload, not scrolling/MMC4/MMC5 evidence']}
assert r['payload_only_ms_per_frame']>framebudget and r['total_wire_ms_per_frame']>framebudget
assert all(x>framebudget for x in r['scenario_floor_ms'].values())
a.out.parent.mkdir(parents=True,exist_ok=True);a.out.write_text(json.dumps(r,indent=2)+'\n',encoding='utf8');print(json.dumps({k:r[k] for k in ['mean_ms_per_display','phases','total_wire_ms_per_frame','payload_only_ms_per_frame','minimum_fixed_wait_ms_per_frame','planner_excluding_emit_callback_ms','scenario_floor_ms']}))
